(
  $model := $state.context.component.model;
  $fieldName := field.name;
  $dataPath := $state.context.component.(
    $exists(joinPrefix) ? joinPrefix & "."
  ) & $fieldName;
  $labelField := $coalesce([$state.context.component.labelField, "id"]);

  $scalarMap := {
    "String": {
      "format": $fieldName = "description" or $fieldName = "note" ? 'markdown' : 'text'
    },
    "Email": {
      "format": 'text'
    },
    "Boolean": {
      "format": 'checkmark'
    },
    "DateTime": {
      "format": 'datetime'
    },
    "Int": {
      "format": 'integer'
    },
    "Float": {
      "format": 'float'
    },
    "JSON": {
      "format": 'json'
    },
    "JSONObject": {
      "format": 'json'
    },
    "Address": {
      "format": 'address',
      "query": {
        "fields": [
          $dataPath & '.lines',
          $dataPath & '.city',
          $dataPath & '.state',
          $dataPath & '.postalCode',
          $dataPath & '.country'
        ]
      }
    },
    "Measure": {
      "format": 'measure',
      "query": {
        "fields": [
          $dataPath & '.value',
          $dataPath & '.unit.code',
          $dataPath & '.unit.id'

        ]
      }
    },
    "RatioMeasure": {
      "format": 'ratioMeasure',
      "query": {
        "fields": [
          $dataPath & '.numeratorValue',
          $dataPath & '.numeratorUnit.code',
          $dataPath & '.numeratorUnit.id',
          $dataPath & '.denominatorUnit.code',
          $dataPath & '.denominatorUnit.id'
        ]
      }
    }
  };

  $format := $lookup($scalarMap, baseType);

  $map([$format ? $format : {}], function($v) {
    $merge([
      { 
        "name": $fieldName,
        "description": field.description,
        "label": $startCase($fieldName),
        "format": "text",
        "dataPath": $dataPath,
        "query": {
          "fields": [
             $dataPath
          ]
        }
      },
      $v,
      ($fieldName = $labelField or $fieldName = 'id') ? {
        "linkTarget": {
            "__transform": '"/' 
              & $model.metadata.mfgx.module.group.id 
              & '/' 
              & $model.metadata.mfgx.module.id 
              & '/'
              & $pluralize($lowerFirst($model.name),'en')
              & '/'
              & '" & data.id'
        },
        "query": {
          "fields": [
             $dataPath,
            "id"
          ]
        }
      } : {}
    ])
  })  
)

