(
  $fieldName := field.name;
  $dataPath := $state.context.component.(
    $exists(joinPrefix) ? joinPrefix & "."
  ) & $fieldName;
  $labelField := $coalesce([
    baseTypeModel.metadata.mfgx.isDataChangeModel ? undefined : baseTypeModel.metadata.mfgx.labelField, 
    "id"
  ]);

  { 
    "name": $fieldName,
    "description": field.description,
    "label": $startCase($fieldName),
    "dataPath": $dataPath & '.total',
    "dataQuery": {
      "model": baseType,
      "api": $state.context.parameters.api,
      "fields": ["id"]
    },    
    "additionalFilter": {
      "__transform": '{
        "' & field.metadata.mfgx.relation.fields.to & '": {
          "_eq": data.id
        }
      }'
    },
    "format": 'dynamicListDialog',
    "columns": [
      {
        "name": $labelField,
        "label": $startCase($labelField),
        "dataPath": $labelField,
        "format": 'text',
        "linkTarget": {
          "__transform": '"/' 
            & baseTypeModel.metadata.mfgx.module.group.id 
            & '/' 
            & baseTypeModel.metadata.mfgx.module.id 
            & '/'
            & $pluralize($lowerFirst(baseType),'en')
            & '/'
            & '" & data.id'
        },
        "query": {
          "fields": $distinct([
            "id",
            $labelField
          ])
        }
      }
    ]
  }
)

(
  $standardFields := [
    'id',
    'createdAt',
    'createdByUser',
    'createdByUserId',
    'dataChanges',
    'updatedAt',
    'updatedByUser',
    'updatedByUserId',
    $state.context.component.parameterField
  ];

  $getFieldToExpand := function( $model) {(

    $joinField := $filter($model.fields, function($v) {
      $not($exists($standardFields[$=$v.name])) and 
      ($v.type = 'ID')
    });

    $expandField := $model.fields[
      metadata.mfgx.relation.fields.from =
      $joinField.name
    ];

    $isNil($expandField) ?
      $throw('Error generating the columns of the linked type.  
      The field, ' & $joinField.name & ', does not realize to a type.') :
      $expandField;

  )};

  $fieldToExpand := payload.component.model ~> $getFieldToExpand;

  $expandedFields := function($field) {(
    $baseTypeMatch := $match($field.type, /\[?(\w+)!?\]?!?/);
    $baseType := $baseTypeMatch.groups[0];

    $prefix := $field.name & '.';

    $model := $executeTransform("getModelByName", 
      {
        "api": $state.context.parameters.api,
        "name": $baseType
      }
    );
  )}; 

  $expandedModel := $fieldToExpand 
  ~> $expandedFields;

  {
    "model": $expandedModel,
    "labelField": $expandedModel.metadata.mfgx.( labelField ? labelField : 'id'),
    "joinPrefix": $fieldToExpand.name
  }
)

